const read=rel=>JSON.parse(fs.readFileSync(path.join(ROOT,rel),'utf8'));
const writeJson=(rel,value)=>{const full=path.join(ROOT,rel);fs.mkdirSync(path.dirname(full),{recursive:true});fs.writeFileSync(full,JSON.stringify(value,null,2)+'\n');};
const writeText=(rel,value)=>{const full=path.join(ROOT,rel);fs.mkdirSync(path.dirname(full),{recursive:true});fs.writeFileSync(full,value.endsWith('\n')?value:value+'\n');};

