const PHASE_FRAME={
  morning:'Morgenen handler om arbeidsobjekt, myndighet og avgrensning: før noe sendes videre må aktiv tittel, faktisk fullmakt, beslutningseier, versjon og åpne premisser stå i regjeringssaken.',
  lunch:'Lunsjen gjør maktrelasjonene synlige: samme grep kan styrke tillit hos ett publikum og svekke den hos et annet, fordi kollegialitet, faglighet, kontroll, offentlighet og privatliv vurderer rollen forskjellig.',
  afternoon:'Ettermiddagen tvinger fram prioritering, venting, eskalering eller korrekt formell beslutning. Spilleren må kunne være politisk tydelig uten å gjøre status, krise, nærhet eller et felles role_scope til ekstra myndighet.',
  evening:'Kvelden viser privat og forsinket konsekvens. Arbeidsvalget følger spilleren ut av møtet gjennom tillit, ansvar, sikkerhet, arbeidspress og identitet, men ingen sosial reaksjon kan endre den formelle myndighetsgrensen.'
};
function beatSummary(day,phase,title){return `Dag ${day}, ${phase}, tittelspor ${title}: ${DAY_TOPICS[day-1]} ${PHASE_FRAME[phase]} ${PERSISTENT} oppdateres med public_office_appointment, aktiv tittel, portefølje og delegasjon, politisk mål, bestilling, beslutningseier, gjeldende dokumentversjon, faglig grunnlag, rettslig hjemmel, budsjett og usikkerhet, departementsposisjoner, samordning, fortrolighet, parti-stat-grense, politisk anbefaling, korrekt formell beslutning, offentlig begrunnelse, iverksetting, ventepunkt, handoff og senere resultat. Statssekretær, Statsråd (minister) og Statsminister deler samme arbeidsverden, men aldri automatisk hverandres myndighet. Spilleren må derfor skille koordinering fra overstyring, faglig premiss fra politisk valg, partiets interesse fra statens ressursbruk, fortrolig kunnskap fra offentlig argument og rask respons fra korrekt beslutningsform. Når nye fakta, juridiske premisser, budsjettall eller gjennomføringsfunn oppstår, brukes bounded rework: bare berørte ledd åpnes igjen, mens tidligere dokumentversjon, råd, beslutning, ansvar og kommunikasjon beholdes. Dermed blir beatet en konkret prøve på demokratisk og konstitusjonell maktbruk, ikke bare på å vinne dagens politiske konflikt.`;}
function standingConsequence(audience,day,phase){return `Standing hos ${audience} kan endres på dag ${day}/${phase} fordi gruppen vurderer konkret pålitelighet i tittelbruk, beslutningsspor, faglig redelighet, samordning, fortrolighet, parti-stat-grense og korrigerbarhet. Tillit kan divergere mellom regjering, embetsverk, andre departementer, Storting, offentlighet, gjennomføringsledd og private relasjoner. Reaksjonen kan påvirke samarbeid og sosial tilgang, men kan aldri gi Statssekretær, Statsråd (minister) eller Statsminister public_office_appointment, en annen tittel, ny delegasjon, fortrolighetstilgang eller beslutningsmyndighet, og kan aldri gjøre History Go, Politikk-badge, nettverk eller popularitet til evidens for dagens sak.`;}

const coverage=[];
let idx=0;
for(let day=1;day<=14;day++)for(const phase of PHASES){
  const title=TITLES[(day-1)%TITLES.length];
  const thread=THREADS[idx%THREADS.length].id;
  const audience=AUDIENCES[(idx+day)%AUDIENCES.length];
  coverage.push({day,phase,beat_type:PHASE_TYPE[phase],summary:beatSummary(day,phase,title),thread_ids:[thread],materialization_refs:[refs[idx%refs.length]],standing_audience:audience,standing_consequence:standingConsequence(audience,day,phase)});
  idx++;
}
const primaryThreads=THREADS.map((t,i)=>({
  id:t.id,
  relationship:`Denne tråden følger ${t.focus}. Relasjonen utvikler seg langsomt over flere dager fordi spilleren ikke bare blir vurdert på utfallet, men på om beslutningssporet tåler senere uenighet, kontroll og nye fakta. En kortsiktig politisk gevinst kan derfor svekke langsiktig standing dersom tittel, fullmakt, faggrunnlag eller ansvar gjøres uklart, mens et vanskelig nei eller en åpen korrigering kan koste status nå og styrke institusjonell tillit senere. Statssekretær, Statsråd og Statsminister leses ulikt fordi de har ulike formelle posisjoner; ingen sosial standing kan gjøre dem utskiftbare eller erstatte public_office_appointment.`,
  beat_refs:coverage.filter(b=>b.thread_ids.includes(t.id)).map(b=>`${b.day}/${b.phase}`)
}));
const privateAftermath=THREADS.map((t,i)=>({id:`private_${t.id}`,description:`Etter arbeidsdagen fortsetter ${t.focus}. Den private konsekvensen handler ikke om en skjult belønningsscore, men om hvordan maktnært arbeid endrer språk, tilgjengelighet, trygghet og forholdet til egen rolle. Spilleren kan oppleve stolthet, skyld, søvnmangel, avstand eller lettelse når et upopulært premiss ble stående, en kollega ble overkjørt, en korrigering ble offentlig eller en beslutning faktisk virket. Privat støtte, sosial prestisje og nærhet til sterke personer kan påvirke motivasjon og relasjoner, men kan aldri gi public_office_appointment, fortrolighetstilgang eller offentlig myndighet. Det som ble besluttet og dokumentert i ${PERSISTENT} forblir canonicalt selv når spilleren ønsker at historien så annerledes ut.`,materialization_refs:[refs[i%refs.length]]}));
