writeText(SOURCE,[
'# Politikk / Regjeringsledelse — Role World rollout source-first closure','',
'## Scope lock','',
'- One canonical role scope only: `politikk/politikk_regjeringsledelse`.','- `Statssekretær`, `Statsråd (minister)` and `Statsminister` remain `appointment_required` and each requires `public_office_appointment`.','- A shared role_scope never makes the three titles authority-interchangeable.','- No new runtime and no parallel scene format.','- Existing role model, work grammar, 16-step plan, 4 fictional actors, 4 work surfaces, 15 canonical mails, persistent government-case object, waiting/handoff/rework and authority boundary are preserved.','',
'## Authored realism dimension','',
'- Only `situated_reputation` is authored in this rollout.','- No global reputation score. Standing is audience-specific and cannot grant appointment, title, delegation, confidential access, evidence or decision authority.','- Nine slow axes are editorial-only until governed; none becomes a runtime authority score.','',
'## Government-specific authority','',
'- Statssekretær remains bounded by actual assignment/delegation and cannot inherit ministerial or prime-ministerial authority.','- Statsråd retains the concrete portfolio responsibility and only the decisions available through law and the correct formal process.','- Statsminister leads and coordinates government but is not modeled as unlimited personal authority replacing ministers, collegial government, Parliament or other constitutional organs.','- History Go and the Politikk badge can improve historical and institutional questions but cannot supply current public_office_appointment, evidence, legal authority, budget authority, confidential access or a current decision.','',
'## Cross-role boundary','',
'- `cross_role_need` remains `not_required_for_rollout`.','- No shared runtime object is inferred from thematic proximity to Parliamentary work or Political advisory work.','',
'## Season and editorial uniqueness','',
'- 14 days × 4 phases = 56 unique dramaturgical beats.','- Seven primary threads each recur eight times across multiple days.','- Eight government-specific recurring archetypes, seven situated audiences, nine slow standing axes, private aftermath and delayed consequences are authored for this role.','- Editorial uniqueness comes from title-bound authority, portfolio responsibility, cabinet collegiality, interdepartmental coordination, party-state boundaries, parliamentary control, implementation and correction — not from copying another political Role World.','',
'## Materialization','',
'- All 15 canonical prerequisite mail references are reused; each appears at least three times across the 56-beat coverage grid.','- No new runtime state is introduced. The existing scene pipeline remains canonical.'
].join('\n'));

const test=`const assert=require('node:assert/strict');\nconst fs=require('node:fs'),path=require('node:path');const ROOT=path.resolve(__dirname,'..');const read=rel=>JSON.parse(fs.readFileSync(path.join(ROOT,rel),'utf8'));const text=rel=>fs.readFileSync(path.join(ROOT,rel),'utf8');const exists=rel=>fs.existsSync(path.join(ROOT,rel));\nconst CATEGORY='${CATEGORY}',ROLE='${ROLE}',KEY='${KEY}',WORLD='${WORLD}',MODEL='${MODEL}',GRAMMAR='${GRAMMAR}',PLAN='${PLAN}',SOURCE='${SOURCE}',PERSISTENT='${PERSISTENT}';const TYPES=${JSON.stringify(TYPES)},TITLES=${JSON.stringify(TITLES)},THEMES=${JSON.stringify(THEMES)},AUDIENCES=${JSON.stringify(AUDIENCES)};const catalogPath=type=>'data/Civication/mailFamilies/'+CATEGORY+'/'+type+'/'+ROLE+'_'+type+'.json';const refs=TYPES.flatMap(type=>{const d=read(catalogPath(type));return (d.families||[]).flatMap(f=>(f.mails||[]).map(m=>catalogPath(type)+'#'+m.id));});\nfor(const rel of [WORLD,MODEL,GRAMMAR,PLAN,SOURCE])assert.ok(exists(rel),rel+' missing');const world=read(WORLD),model=read(MODEL),grammar=read(GRAMMAR),plan=read(PLAN);assert.equal(world.schema,'civication_role_world_v1');assert.equal(world.version,1);assert.equal(world.category,CATEGORY);assert.equal(world.role_scope,ROLE);assert.equal(world.status,'role_world_complete');assert.deepEqual(world.theme_ids,THEMES);assert.equal(plan.sequence.length,16);assert.equal(model.related_people.length,4);assert.equal(refs.length,15);assert.equal(new Set(refs).size,15);for(const t of TITLES)assert.deepEqual(grammar.day_one_contract.entry_policy_by_title[t],{policy:'appointment_required',qualification_ids:['public_office_appointment']});assert.equal(grammar.persistent_work_object_contract.id,PERSISTENT);\nassert.deepEqual(world.materialization.authored_dimensions,['situated_reputation']);for(const k of ['no_new_runtime','existing_plan_preserved','existing_role_model_preserved','existing_people_foundation_preserved','existing_work_grammar_preserved','existing_persistent_work_preserved','existing_rhythm_preserved','career_title_gates_preserved'])assert.equal(world.materialization[k],true,k);assert.equal(world.materialization.cross_role_link_materialized,false);assert.deepEqual(world.materialization.source_refs,refs);assert.equal(world.existing_work_continuity.new_runtime_state,false);assert.deepEqual(world.existing_work_continuity.work_loops,grammar.work_loops);assert.equal(world.existing_work_continuity.persistent_work_object,PERSISTENT);assert.deepEqual(world.existing_work_continuity.waiting_states,grammar.rhythm_contract.waiting_states);\nconst bank=read('data/Civication/roleWorldThemeBank.json');const valid=new Set(bank.themes.map(x=>x.id));for(const id of THEMES)assert.ok(valid.has(id));assert.deepEqual(bank.reference_profiles[KEY],THEMES);assert.equal(world.situated_reputation_model.global_score_allowed,false);assert.deepEqual(world.situated_reputation_model.audiences.map(a=>a.id),AUDIENCES);assert.equal(new Set(world.situated_reputation_model.audiences.map(a=>a.standing_axis)).size,AUDIENCES.length);for(const a of world.situated_reputation_model.audiences){assert.equal(a.cares_about.length,2);assert.ok(a.cannot_grant.length>=420,a.id+'/'+a.cannot_grant.length);for(const term of [/kan ikke/i,/Statssekretær/i,/Statsråd/i,/Statsminister/i,/public_office_appointment/i,/History Go/i,/Politikk-badge/i,/evidens/i,/beslutning/i])assert.match(a.cannot_grant,term);}assert.ok(world.situated_reputation_model.divergence_examples.length>=8);for(const term of [/global/i,/Statssekretær/i,/Statsråd/i,/Statsminister/i,/appointment_required/i,/public_office_appointment/i,/delegasjon/i,/fortrolig/i,/History Go/i,/Politikk-badge/i,/kollegial/i])assert.match(world.situated_reputation_model.authority_separation,term);assert.equal(world.slow_axes.length,9);for(const a of world.slow_axes)assert.equal(a.runtime_binding,'editorial_only_until_governed');assert.ok(world.social_environments.length>=8);assert.equal(world.recurring_people_archetypes.length,8);for(const p of world.recurring_people_archetypes)for(const f of ['id','social_function','class_position','status','power_over_player','wants','conceals','speech_style','teaches_player'])assert.ok(String(p[f]||'').trim(),p.id+'/'+f);\nassert.equal(world.history_go_affordance.badge_id,'politikk');assert.ok(refs.includes(world.history_go_affordance.source_ref));assert.ok(world.history_go_affordance.better_question.length>=700);for(const term of [/kan ikke/i,/Statssekretær/i,/Statsråd/i,/Statsminister/i,/public_office_appointment/i,/delegasjon/i,/fortrolig/i,/evidens/i,/beslutning/i])assert.match(world.history_go_affordance.authority_boundary,term);assert.equal(world.cross_role_proof.required_for_rollout,false);assert.equal(world.cross_role_proof.shared_work_object_found,false);assert.equal(world.cross_role_proof.status,'not_required_for_rollout');\nassert.equal(world.season.days,14);assert.deepEqual(world.season.day_phases,['morning','lunch','afternoon','evening']);assert.equal(world.season.coverage.length,56);const beatKeys=new Set(world.season.coverage.map(b=>b.day+'/'+b.phase));assert.equal(beatKeys.size,56);assert.equal(new Set(world.season.coverage.map(b=>b.summary)).size,56);const phaseTypes={morning:'task',lunch:'relationship',afternoon:'decision',evening:'private_consequence'};const use=new Map(refs.map(r=>[r,0]));for(const b of world.season.coverage){assert.equal(b.beat_type,phaseTypes[b.phase]);assert.ok(b.summary.length>=650,b.day+'/'+b.phase+'/'+b.summary.length);assert.ok(AUDIENCES.includes(b.standing_audience));assert.ok(b.standing_consequence.length>=300);assert.equal(b.materialization_refs.length,1);const r=b.materialization_refs[0];assert.ok(refs.includes(r));use.set(r,use.get(r)+1);for(const term of [/public_office_appointment/i,/Statssekretær/i,/Statsråd/i,/Statsminister/i])assert.match(b.summary,term);}for(const [r,c] of use)assert.ok(c>=3,r+'/'+c);assert.equal(world.primary_threads.length,7);for(const th of world.primary_threads){assert.ok(th.relationship.length>=350);assert.ok(th.beat_refs.length>=5&&th.beat_refs.length<=10);assert.ok(new Set(th.beat_refs.map(r=>r.split('/')[0])).size>=2);for(const r of th.beat_refs){assert.ok(beatKeys.has(r));const b=world.season.coverage.find(x=>x.day+'/'+x.phase===r);assert.ok(b.thread_ids.includes(th.id));}}assert.ok(world.private_aftermath.length>=6);for(const a of world.private_aftermath){assert.ok(a.description.length>=350);for(const r of a.materialization_refs)assert.ok(refs.includes(r));}assert.ok(world.delayed_consequences.length>=8);\nconst index=read('data/Civication/roleWorlds/index.json');const rows=index.roles.filter(r=>r.category===CATEGORY&&r.role_scope===ROLE);assert.equal(rows.length,1);assert.deepEqual(rows[0],{category:CATEGORY,role_scope:ROLE,status:'role_world_complete',path:WORLD});assert.match(index.status,/_role_worlds_materialized$/);const checklist=read('data/Civication/roleWorldAuthoringChecklist.json');assert.equal(checklist.reference_worlds.filter(x=>x===WORLD).length,1);const readiness=read('data/Civication/roleWorldRolloutReadiness.json');const ready=readiness.roles.find(r=>r.key===KEY);assert.ok(ready);assert.equal(ready.classification,'rollout_ready');assert.equal(ready.role_world_status,'role_world_complete');assert.equal(ready.already_reference_or_pilot,true);assert.deepEqual(ready.authored_work_required,[]);assert.ok(!(readiness.rollout_queue||[]).some(r=>r.key===KEY));assert.equal(ready.cross_role.need,'not_required_for_rollout');const career=read('data/Civication/careerGameplayMatrix.json').worlds.find(r=>r.key===KEY);assert.equal(career.status,'playable');assert.equal(career.audit.runtime_gate,true);assert.deepEqual(career.audit.missing_components,[]);const policies=Object.fromEntries(career.audit.salary.rows.map(r=>[r.title,r.offer_policy]));for(const t of TITLES)assert.equal(policies[t],'appointment_required');const scenario=read('data/Civication/scenarioPeople/generated/politikk.json');const factual=new Set(Object.values(scenario.people_pool||{}).flat().map(p=>p.person_id));for(const p of model.related_people)assert.ok(!factual.has(p.id));const source=text(SOURCE);for(const term of [/Scope lock/i,/Statssekretær.*Statsråd.*Statsminister.*appointment_required/is,/public_office_appointment/i,/situated_reputation/i,/No global reputation score/i,/not_required_for_rollout/i,/History Go/i,/No new runtime/i,/Editorial uniqueness/i,/15 canonical/i,/14 days.*4 phases.*56/i])assert.match(source,term);console.log('Civication Politikk Regjeringsledelse Role World rollout: OK');\n`;
writeText(TEST,test);

